// Fails when a password generated by the e2e tests appears in any file about
// to be uploaded as a CI artifact. Runs after the tests and before the upload
// steps (.github/workflows/ci.yml); the uploads only run when it passes.
//
// Scans every file under the uploaded folders as raw bytes, and the entries
// of every .zip (Playwright traces) after extracting them with `unzip -p`.
// Screenshots are images: text in them cannot be searched here, so the tests
// check the page before every capture (e2e/secrets.ts, assertNoSecretOnPage).
// It prints file paths only, never a value.

import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

const SECRETS_FILE = path.join(process.cwd(), ".e2e-secrets", "generated.txt");
const UPLOADED = ["test-results", "playwright-report"];

const secrets = existsSync(SECRETS_FILE)
  ? [...new Set(readFileSync(SECRETS_FILE, "utf8").split("\n").filter(Boolean))]
  : [];

function* files(dir) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    const full = path.join(dir, name);
    if (statSync(full).isDirectory()) yield* files(full);
    else yield full;
  }
}

function contains(buffer) {
  return secrets.some((secret) => buffer.includes(Buffer.from(secret, "utf8")));
}

function zipEntries(file) {
  const list = execFileSync("unzip", ["-Z1", file], { encoding: "utf8" });
  return list.split("\n").filter((entry) => entry && !entry.endsWith("/"));
}

const found = [];
let scanned = 0;
for (const root of UPLOADED) {
  for (const file of files(root)) {
    scanned += 1;
    if (contains(readFileSync(file))) found.push(file);
    if (file.endsWith(".zip")) {
      for (const entry of zipEntries(file)) {
        const data = execFileSync("unzip", ["-p", file, entry], { maxBuffer: 256 * 1024 * 1024 });
        if (contains(data)) found.push(`${file} :: ${entry}`);
      }
    }
  }
}

if (found.length > 0) {
  console.error(`A generated password appears in ${found.length} artifact file(s):`);
  for (const file of found) console.error(`  ${file}`);
  process.exit(1);
}
console.log(`Artifact scan: ${secrets.length} generated password(s) checked against ${scanned} file(s); none found.`);
